-- Contact issue tracking
CREATE TABLE IF NOT EXISTS lead_contact_issues (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), lead_id UUID NOT NULL REFERENCES leads(id) ON DELETE CASCADE, reported_by_user_id UUID NOT NULL REFERENCES users(id), issue_type TEXT NOT NULL CHECK (issue_type IN ('NO_PHONE','NOT_ON_WHATSAPP')), status TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','RESOLVED')), notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ, resolved_by_user_id UUID REFERENCES users(id), resolution_notes TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_one_open_contact_issue_per_lead ON lead_contact_issues(lead_id) WHERE status='OPEN';